"""Adds reading passages ("קטעי קריאה") taken from the activity files Roni attached to src/data/readings.json.

Policy (Roni's final decision): every reading passage is added IN FULL, word for word as in the source file, with the author and source
as the file states them (summaries are not used). Only extraction errors / line order were fixed and personal dedications left out.
Song lyrics (e.g. "נשמות צמאות") are not copied.

Idempotent: ids that already exist are skipped. Nothing is written on import; run `python3 add_readings_from_files.py`
(or with --dry-run to validate and print only).
"""
import sys
from content_tools import load, save, age_label

DOMAINS = ('ערכי', 'אמוני', 'שניהם')
# words that must never appear in the readings (client request)
BANNED = ['קמה', 'גרעין', 'אשקלון', 'עזרא']

NEW = []


def R(id, title, domain, ages, description, text, howToUse, source, tags, link=None):
    lo, hi = ages
    r = {'id': id, 'title': title, 'domain': domain, 'ageLabel': age_label(lo, hi), 'ageMin': lo, 'ageMax': hi,
         'description': description, 'text': text, 'howToUse': howToUse, 'source': source, 'tags': tags}
    if link:
        r['sourceLink'] = {'title': link[0], 'url': link[1]}
    NEW.append(r)


